// bruteArea expands from each bar, which is the O(n^2) solution the big test
// is sized to rule out.
func bruteArea(heights []int) int {
	best := 0
	for i := range heights {
		lo := heights[i]
		for j := i; j < len(heights); j++ {
			if heights[j] < lo {
				lo = heights[j]
			}
			if area := lo * (j - i + 1); area > best {
				best = area
			}
		}
	}
	return best
}

