// largestRectangleArea keeps a stack of indices whose heights are strictly
// increasing; a bar is popped once its right boundary is known.
func largestRectangleArea(heights []int) int {
	stack := make([]int, 0, len(heights)+1)
	best := 0
	for i := 0; i <= len(heights); i++ {
		h := 0
		if i < len(heights) {
			h = heights[i]
		}
		for len(stack) > 0 && heights[stack[len(stack)-1]] >= h {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			left := -1
			if len(stack) > 0 {
				left = stack[len(stack)-1]
			}
			if area := heights[top] * (i - left - 1); area > best {
				best = area
			}
		}
		stack = append(stack, i)
	}
	return best
}

