// bruteDistance is the plain recursion, used only on very short strings.
func bruteDistance(a, b string) int {
	if len(a) == 0 {
		return len(b)
	}
	if len(b) == 0 {
		return len(a)
	}
	if a[0] == b[0] {
		return bruteDistance(a[1:], b[1:])
	}
	best := bruteDistance(a[1:], b)
	if d := bruteDistance(a, b[1:]); d < best {
		best = d
	}
	if d := bruteDistance(a[1:], b[1:]); d < best {
		best = d
	}
	return best + 1
}

func TestMinDistanceSmallCases(t *testing.T) {
	cases := []struct {
		a, b string
		want int
	}{
		{"horse", "ros", 3},
		{"intention", "execution", 5},
		{"", "", 0},
		{"", "abc", 3},
		{"abc", "", 3},
		{"same", "same", 0},
		{"a", "b", 1},
		{"kitten", "sitting", 3},
		{"flaw", "lawn", 2},
	}
	for _, c := range cases {
		if got := minDistance(c.a, c.b); got != c.want {
			t.Fatalf("minDistance(%q, %q) = %d, want %d", c.a, c.b, got, c.want)
		}
	}
}

func TestMinDistanceMatchesBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	letters := []byte("abc")
	pick := func(n int) string {
		out := make([]byte, n)
		for i := range out {
			out[i] = letters[rng.Intn(len(letters))]
		}
		return string(out)
	}
	for trial := 0; trial < 200; trial++ {
		a, b := pick(rng.Intn(7)), pick(rng.Intn(7))
		if got, want := minDistance(a, b), bruteDistance(a, b); got != want {
			t.Fatalf("trial %d: minDistance(%q, %q) = %d, want %d", trial, a, b, got, want)
		}
