// TestMinDistanceOnLongStrings is far past what an unmemoised recursion can
// do: the answer is planted by building b from a with a known edit script.
func TestMinDistanceOnLongStrings(t *testing.T) {
	rng := rand.New(rand.NewSource(9))
	const n = 4000
	a := make([]byte, n)
	for i := range a {
		a[i] = byte('a' + rng.Intn(20))
	}
	// b is a with every 40th byte substituted for one that cannot match.
	b := append([]byte(nil), a...)
	edits := 0
	for i := 0; i < n; i += 40 {
		b[i] = 'z'
		if a[i] != 'z' {
			edits++
		}
	}
	if got := minDistance(string(a), string(b)); got != edits {
		t.Fatalf("planted %d substitutions over %d bytes, got %d", edits, n, got)
	}
}

