import (
	"math/rand"
	"testing"
)

// minCut brute-forces the minimum s-t cut by trying every vertex subset, which
// max-flow must equal. Only usable for very small n.
func minCut(n int, edges [][]int, s, t int) int {
	best := -1
	for mask := 0; mask < 1<<n; mask++ {
		if mask&(1<<s) == 0 || mask&(1<<t) != 0 {
			continue
		}
		sum := 0
		for _, e := range edges {
			if mask&(1<<e[0]) != 0 && mask&(1<<e[1]) == 0 {
				sum += e[2]
			}
		}
		if best < 0 || sum < best {
			best = sum
		}
	}
	return best
}

func TestMaxFlowSmallCases(t *testing.T) {
	// The textbook 6-node network.
	edges := [][]int{
		{0, 1, 16}, {0, 2, 13},
		{1, 2, 10}, {1, 3, 12},
		{2, 1, 4}, {2, 4, 14},
		{3, 2, 9}, {3, 5, 20},
		{4, 3, 7}, {4, 5, 4},
	}
	if got := maxFlow(6, edges, 0, 5); got != 23 {
		t.Fatalf("textbook network gave %d, want 23", got)
	}
	if got := maxFlow(2, [][]int{{0, 1, 5}, {0, 1, 6}}, 0, 1); got != 11 {
		t.Fatalf("parallel arcs gave %d, want 11", got)
	}
	if got := maxFlow(3, [][]int{{0, 1, 5}}, 0, 2); got != 0 {
		t.Fatalf("unreachable sink gave %d, want 0", got)
	}
	if got := maxFlow(4, [][]int{{0, 1, 100}, {1, 2, 3}, {2, 3, 100}}, 0, 3); got != 3 {
		t.Fatalf("bottleneck chain gave %d, want 3", got)
	}
}

func TestMaxFlowMatchesMinCut(t *testing.T) {
	rng := rand.New(rand.NewSource(17))
	for trial := 0; trial < 200; trial++ {
		const n = 7
		edges := make([][]int, 0, 20)
		for u := 0; u < n; u++ {
			for v := 0; v < n; v++ {
				if u != v && rng.Intn(3) == 0 {
					edges = append(edges, []int{u, v, 1 + rng.Intn(9)})
				}
			}
		}
		want := minCut(n, edges, 0, n-1)
		got := maxFlow(n, cloneEdges(edges), 0, n-1)
		if got != want {
			t.Fatalf("trial %d: maxFlow = %d, min cut = %d, edges %v", trial, got, want, edges)
		}
	}
}

func cloneEdges(edges [][]int) [][]int {
	out := make([][]int, len(edges))
	for i, e := range edges {
		out[i] = append([]int(nil), e...)
	}
	return out
}

