// TestMaxFlowOnBipartiteMatching reads a perfect matching off a max flow: 2000
// left nodes each joined to 20 right nodes, with one planted perfect matching.
func TestMaxFlowOnBipartiteMatching(t *testing.T) {
	rng := rand.New(rand.NewSource(23))
	const half = 2000
	n := 2*half + 2
	source, sink := 2*half, 2*half+1
	edges := make([][]int, 0, half*22)
	for i := 0; i < half; i++ {
		edges = append(edges, []int{source, i, 1})
		edges = append(edges, []int{half + i, sink, 1})
		edges = append(edges, []int{i, half + i, 1}) // the planted matching
		for k := 0; k < 20; k++ {
			edges = append(edges, []int{i, half + rng.Intn(half), 1})
		}
	}
	if got := maxFlow(n, edges, source, sink); got != half {
		t.Fatalf("bipartite matching gave %d, want %d", got, half)
	}
}

