// maxFlow is Dinic: repeatedly build a level graph with BFS, then push blocking
// flow along it with a DFS that keeps a per-node iterator over its arcs.
type flowEdge struct {
	to, rev, cap int
}

func maxFlow(n int, edges [][]int, s, t int) int {
	graph := make([][]flowEdge, n)
	for _, e := range edges {
		u, v, c := e[0], e[1], e[2]
		graph[u] = append(graph[u], flowEdge{to: v, rev: len(graph[v]), cap: c})
		graph[v] = append(graph[v], flowEdge{to: u, rev: len(graph[u]) - 1, cap: 0})
	}
	level := make([]int, n)
	iter := make([]int, n)
	queue := make([]int, 0, n)

	bfs := func() bool {
		for i := range level {
			level[i] = -1
		}
		level[s] = 0
		queue = append(queue[:0], s)
		for i := 0; i < len(queue); i++ {
			u := queue[i]
			for _, e := range graph[u] {
				if e.cap > 0 && level[e.to] < 0 {
					level[e.to] = level[u] + 1
					queue = append(queue, e.to)
				}
			}
		}
		return level[t] >= 0
	}

	var dfs func(u, limit int) int
	dfs = func(u, limit int) int {
		if u == t {
			return limit
		}
		for ; iter[u] < len(graph[u]); iter[u]++ {
			e := &graph[u][iter[u]]
			if e.cap <= 0 || level[e.to] != level[u]+1 {
				continue
			}
			push := limit
			if e.cap < push {
				push = e.cap
			}
			got := dfs(e.to, push)
			if got > 0 {
				e.cap -= got
				graph[e.to][e.rev].cap += got
				return got
			}
			level[e.to] = -1
		}
		return 0
	}

	const inf = int(^uint(0) >> 1)
	total := 0
	for bfs() {
		for i := range iter {
			iter[i] = 0
		}
		for {
			got := dfs(s, inf)
			if got == 0 {
				break
			}
			total += got
		}
	}
	return total
}
